nextflow_process {

    name "Test Process MOBSUITE_RECON"
    script "../main.nf"
    process "MOBSUITE_RECON"

    tag "modules"
    tag "modules_nfcore"
    tag "mobsuite"
    tag "mobsuite/recon"

    test("test-mobsuite-recon") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
				    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("test-mobsuite-recon-stub") {
        options '-stub'

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
				    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

}
